  "ЦИФРОВИ ДОКАЗАТЕЛСТВА":{en:"DIGITAL EVIDENCE",de:"DIGITALE BEWEISE",fr:"PREUVES NUMÉRIQUES",pl:"DOWODY CYFROWE",es:"PRUEBAS DIGITALES"},
