  "Няма събрани доказателства. Започни с огледа.":{en:"No evidence collected yet. Start with the scene.",de:"Noch keine Beweise gesammelt. Beginne am Tatort.",fr:"Aucune preuve recueillie. Commencez par la scène.",pl:"Nie zebrano dowodów. Zacznij od oględzin.",es:"No has reunido pruebas. Empieza por la escena."},
  "Каква е твоята версия?":{en:"What is your theory?",de:"Was ist deine Theorie?",fr:"Quelle est votre hypothèse ?",pl:"Jaka jest twoja teoria?",es:"¿Cuál es tu teoría?"},
  "Обясни мотив и последователност":{en:"Explain motive and sequence",de:"Motiv und Ablauf erläutern",fr:"Expliquez le mobile et la chronologie",pl:"Wyjaśnij motyw i przebieg",es:"Explica motivo y secuencia"},
  "ПРЕДПОЛАГАЕМ МОТИВ":{en:"SUSPECTED MOTIVE",de:"VERMUTETES MOTIV",fr:"MOBILE SUPPOSÉ",pl:"DOMNIEMANY MOTYW",es:"POSIBLE MOTIVO"},
  "ХРОНОЛОГИЯ И ВЪЗМОЖНОСТ":{en:"TIMELINE AND OPPORTUNITY",de:"CHRONOLOGIE UND GELEGENHEIT",fr:"CHRONOLOGIE ET OCCASION",pl:"CHRONOLOGIA I MOŻLIWOŚĆ",es:"CRONOLOGÍA Y OPORTUNIDAD"},
  "ЗАКЛЮЧЕНИЕТО СЕ ОЦЕНЯВА ПО ДОКАЗАТЕЛСТВАТА":{en:"CONCLUSIONS ARE SCORED AGAINST EVIDENCE",de:"SCHLÜSSE WERDEN AN BEWEISEN GEMESSEN",fr:"LES CONCLUSIONS SONT ÉVALUÉES SUR LES PREUVES",pl:"WNIOSKI OCENIA SIĘ NA PODSTAWIE DOWODÓW",es:"LAS CONCLUSIONES SE EVALÚAN SEGÚN LAS PRUEBAS"},
  "Прегледай финалния доклад":{en:"Review final report",de:"Abschlussbericht ansehen",fr:"Lire le rapport final",pl:"Przejrzyj raport końcowy",es:"Revisar informe final"},
  "КОНТЕКСТЕН ПАНЕЛ":{en:"CONTEXT PANEL",de:"KONTEXTPANEL",fr:"PANNEAU CONTEXTUEL",pl:"PANEL KONTEKSTOWY",es:"PANEL CONTEXTUAL"},
